FUNCTION  synthdid_estimate 
function (Y, N0, T0, X = array(dim = c(dim(Y), 0)), noise.level = sd(apply(Y[1:N0, 
    1:T0], 1, diff)), eta.omega = ((nrow(Y) - N0) * (ncol(Y) - 
    T0))^(1/4), eta.lambda = 1e-06, zeta.omega = eta.omega * 
    noise.level, zeta.lambda = eta.lambda * noise.level, omega.intercept = TRUE, 
    lambda.intercept = TRUE, weights = list(omega = NULL, lambda = NULL), 
    update.omega = is.null(weights$omega), update.lambda = is.null(weights$lambda), 
    min.decrease = 1e-05 * noise.level, max.iter = 10000, sparsify = sparsify_function, 
    max.iter.pre.sparsify = 100) 
{
    stopifnot(nrow(Y) > N0, ncol(Y) > T0, length(dim(X)) %in% 
        c(2, 3), dim(X)[1:2] == dim(Y), is.list(weights), is.null(weights$lambda) || 
        length(weights$lambda) == T0, is.null(weights$omega) || 
        length(weights$omega) == N0, !is.null(weights$lambda) || 
        update.lambda, !is.null(weights$omega) || update.omega)
    if (length(dim(X)) == 2) {
        dim(X) = c(dim(X), 1)
    }
    if (is.null(sparsify)) {
        max.iter.pre.sparsify = max.iter
    }
    N1 = nrow(Y) - N0
    T1 = ncol(Y) - T0
    if (dim(X)[3] == 0) {
        weights$vals = NULL
        weights$lambda.vals = NULL
        weights$omega.vals = NULL
        if (update.lambda) {
            Yc = collapsed.form(Y, N0, T0)
            lambda.opt = sc.weight.fw(Yc[1:N0, ], zeta = zeta.lambda, 
                intercept = lambda.intercept, lambda = weights$lambda, 
                min.decrease = min.decrease, max.iter = max.iter.pre.sparsify)
            if (!is.null(sparsify)) {
                lambda.opt = sc.weight.fw(Yc[1:N0, ], zeta = zeta.lambda, 
                  intercept = lambda.intercept, lambda = sparsify(lambda.opt$lambda), 
                  min.decrease = min.decrease, max.iter = max.iter)
            }
            weights$lambda = lambda.opt$lambda
            weights$lambda.vals = lambda.opt$vals
            weights$vals = lambda.opt$vals
        }
        if (update.omega) {
            Yc = collapsed.form(Y, N0, T0)
            omega.opt = sc.weight.fw(t(Yc[, 1:T0]), zeta = zeta.omega, 
                intercept = omega.intercept, lambda = weights$omega, 
                min.decrease = min.decrease, max.iter = max.iter.pre.sparsify)
            if (!is.null(sparsify)) {
                omega.opt = sc.weight.fw(t(Yc[, 1:T0]), zeta = zeta.omega, 
                  intercept = omega.intercept, lambda = sparsify(omega.opt$lambda), 
                  min.decrease = min.decrease, max.iter = max.iter)
            }
            weights$omega = omega.opt$lambda
            weights$omega.vals = omega.opt$vals
            if (is.null(weights$vals)) {
                weights$vals = omega.opt$vals
            }
            else {
                weights$vals = pairwise.sum.decreasing(weights$vals, 
                  omega.opt$vals)
            }
        }
    }
    else {
        Yc = collapsed.form(Y, N0, T0)
        Xc = apply(X, 3, function(Xi) {
            collapsed.form(Xi, N0, T0)
        })
        dim(Xc) = c(dim(Yc), dim(X)[3])
        weights = sc.weight.fw.covariates(Yc, Xc, zeta.lambda = zeta.lambda, 
            zeta.omega = zeta.omega, lambda.intercept = lambda.intercept, 
            omega.intercept = omega.intercept, min.decrease = min.decrease, 
            max.iter = max.iter, lambda = weights$lambda, omega = weights$omega, 
            update.lambda = update.lambda, update.omega = update.omega)
    }
    X.beta = contract3(X, weights$beta)
    estimate = t(c(-weights$omega, rep(1/N1, N1))) %*% (Y - X.beta) %*% 
        c(-weights$lambda, rep(1/T1, T1))
    class(estimate) = "synthdid_estimate"
    attr(estimate, "estimator") = "synthdid_estimate"
    attr(estimate, "weights") = weights
    attr(estimate, "setup") = list(Y = Y, X = X, N0 = N0, T0 = T0)
    attr(estimate, "opts") = list(zeta.omega = zeta.omega, zeta.lambda = zeta.lambda, 
        omega.intercept = omega.intercept, lambda.intercept = lambda.intercept, 
        update.omega = update.omega, update.lambda = update.lambda, 
        min.decrease = min.decrease, max.iter = max.iter)
    return(estimate)
}
