FUNCTION  collapsed.form 
function (Y, N0, T0) 
{
    N = nrow(Y)
    T = ncol(Y)
    rbind(cbind(Y[1:N0, 1:T0, drop = FALSE], rowMeans(Y[1:N0, 
        (T0 + 1):T, drop = FALSE])), cbind(t(colMeans(Y[(N0 + 
        1):N, 1:T0, drop = FALSE])), mean(Y[(N0 + 1):N, (T0 + 
        1):T, drop = FALSE])))
}
